head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50003";
scwin.classInfoDiv3 = null;
scwin.classInfoDiv4 = null;
scwin.dataDiv = "";
scwin.obj = undefined;
scwin.frameId = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(dma_form.get("formCd")); } },
        { childId: "__rb1", attr: "label", fn: function () { return String(dma_form.get("formVer")); } },
        { childId: "txa_formVerUsePurpsDsc", attr: "label", fn: function () { return String(dma_form.get("formVerUsePurpsDsc")); } },
        { childId: "txa_remk", attr: "label", fn: function () { return String(dma_form.get("remk")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.changeInfo();
        scwin.displayInformation($c.util.getComponent('slc_wrtrptMaindocTpCd'));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50003.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

scwin.form_editForm = { action: "", method: 'post', target: '' };

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50003' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50003' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.classInfoDiv3 = $c.util.getComponent('classInfoDiv3');
        scwin.classInfoDiv4 = $c.util.getComponent('classInfoDiv4');
        scwin.init_attrReals();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50003.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_ldMktTpCd_onchange
 * @description slc_ldMktTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_ldMktTpCd_onchange = async function(e){
    try {
        await scwin.changeInfo()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50003.slc_ldMktTpCd_onchange' }); }
};

/**
 * @method
 * @name slc_wrtrptMaindocTpCd_onchange
 * @description slc_wrtrptMaindocTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_wrtrptMaindocTpCd_onchange = function(e){
    try {
        scwin.displayInformation($c.util.getComponent("slc_wrtrptMaindocTpCd"))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50003.slc_wrtrptMaindocTpCd_onchange' }); }
};

/**
 * @method
 * @name slc_formUpclssCd_onchange
 * @description slc_formUpclssCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_formUpclssCd_onchange = async function(e){
    try {
        await scwin.changeInfo()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50003.slc_formUpclssCd_onchange' }); }
};

/**
 * @method
 * @name slc_rsnClssCd_onchange
 * @description slc_rsnClssCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_rsnClssCd_onchange = function(e){
    try {
        scwin.changeInqdisclsInfo()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50003.slc_rsnClssCd_onchange' }); }
};

/**
 * @method
 * @name slc_inqdisclsTpCd_onchange
 * @description slc_inqdisclsTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_inqdisclsTpCd_onchange = function(e){
    try {
        scwin.changeInqdisclsInfo2()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50003.slc_inqdisclsTpCd_onchange' }); }
};

/**
 * @method
 * @name img_234_onclick
 * @description img_234 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_234_onclick = async function(e){
    try {
        await scwin.update()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50003.img_234_onclick' }); }
};

/**
 * @method
 * @name img_235_onclick
 * @description img_235 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_235_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50003.img_235_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Update
 * @description Update 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Update = async function () {
    const sbmOptions = {
        id: "tx_fn_Update",
        method: "post",
        action: "/filing/updateForm.do",
        ref: "dma_UpdateReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_findRsnClasses_xhr
 * @description find Rsn Classes xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_findRsnClasses_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_findRsnClasses_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_findRsnClasses_xhr", unresolved: "action:self_submit:tx_findRsnClasses_xhr" };
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/filing/updateForm.do",
        ref: "dma_loadListReq",
        target: "dlt_byformUsrTpCds=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function () {
    if (($c.util.getComponent('ipt_formEngNm').getValue() == null ? '' : String($c.util.getComponent('ipt_formEngNm').getValue())) === '') {
        $c.util.getComponent("ipt_formEngNm").setValue("N/A");
    }
    if ($c.util.getComponent('slc_wrtrptMaindocTpCd').getValue() !== "1") {
        $c.util.getComponent("slc_rsnClssCd").setValue("");
        $c.util.getComponent("slc_formUpclssCd").setValue("");
    }
    const formUpclssCd = $c.util.getComponent('slc_formUpclssCd').getValue();
    const rsnClssCd = $c.util.getComponent('slc_rsnClssCd').getValue();
    if ((formUpclssCd === "01" && rsnClssCd === "040") || (formUpclssCd === "01" && rsnClssCd === "041") || (formUpclssCd === "09" && rsnClssCd === "006") || (formUpclssCd === "09" && rsnClssCd === "009")) {
        if ($c.util.getComponent('slc_inqdisclsTpCd').getValue() !== "A") {
            $c.util.getComponent("slc_inqdisclsAnsTpCd").setValue("");
        }
    } else {
        $c.util.getComponent("slc_inqdisclsTpCd").setValue("");
        $c.util.getComponent("slc_inqdisclsContnTpCd").setValue("");
        $c.util.getComponent("slc_inqdisclsAnsTpCd").setValue("");
    }
    $c.util.getComponent('dma_UpdateReq').set('method', "updateFormInfo");
    scwin.form_editForm.action = "/filing/updateForm.do";
    await scwin.tx_fn_Update();
};

/**
 * @method
 * @name displayInformation
 * @description display Information 처리
 * @param {*} mainDocObj mainDocObj
 * @returns {void}
 * @hidden N
 */
scwin.displayInformation = function (mainDocObj) {
    let _disabled = false;
    if (mainDocObj.getValue() === "1") {
        scwin.changeInqdisclsInfo();
    } else {
        _disabled = true;
        $c.util.getComponent('slc_inqdisclsTpCd').setDisabled(_disabled);
        $c.util.getComponent('slc_inqdisclsContnTpCd').setDisabled(_disabled);
        $c.util.getComponent('slc_inqdisclsAnsTpCd').setDisabled(_disabled);
    }
    $c.util.getComponent('slc_formUpclssCd').setDisabled(_disabled);
    $c.util.getComponent('slc_rsnClssCd').setDisabled(_disabled);
    if (mainDocObj.getValue() === "1") {
        $c.util.getComponent('txt_text1').setLabel("상장신청서구분");
        ($c.util.getComponent('text2') && $c.util.getComponent('text2').setValue) ? $c.util.getComponent('text2').setValue("상장") : (($c.util.getComponent('text2') && $c.util.getComponent('text2').setText) ? $c.util.getComponent('text2').setText("상장") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'text2'), void ("상장")));
    } else {
        $c.util.getComponent('txt_text1').setLabel("공시비공시구분");
        ($c.util.getComponent('text2') && $c.util.getComponent('text2').setValue) ? $c.util.getComponent('text2').setValue("비공시") : (($c.util.getComponent('text2') && $c.util.getComponent('text2').setText) ? $c.util.getComponent('text2').setText("비공시") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'text2'), void ("비공시")));
    }
};

/**
 * @method
 * @name changeInfo
 * @description change Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeInfo = async function () {
    await scwin.findRsnClasses();
    scwin.changeInqdisclsInfo();
};

/**
 * @method
 * @name changeInqdisclsInfo_
 * @description change Inqdiscls Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeInqdisclsInfo_ = function () {
    const formUpclssCd = $c.util.getComponent('slc_formUpclssCd').getValue();
    const rsnClssCd = $c.util.getComponent('slc_rsnClssCd').getValue();
    if ((formUpclssCd === "01" && rsnClssCd === "040") || (formUpclssCd === "01" && rsnClssCd === "041") || (formUpclssCd === "09" && rsnClssCd === "006") || (formUpclssCd === "09" && rsnClssCd === "009")) {
        scwin.classInfoDiv3.setStyle("display", "block");
        scwin.changeInqdisclsInfo2();
    } else {
        scwin.classInfoDiv3.setStyle("display", "none");
        scwin.classInfoDiv4.setStyle("display", "none");
    }
};

/**
 * @method
 * @name changeInqdisclsInfo
 * @description change Inqdiscls Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeInqdisclsInfo = function () {
    const formUpclssCd = $c.util.getComponent('slc_formUpclssCd').getValue();
    const rsnClssCd = $c.util.getComponent('slc_rsnClssCd').getValue();
    if ((formUpclssCd === "01" && rsnClssCd === "040") || (formUpclssCd === "01" && rsnClssCd === "041") || (formUpclssCd === "09" && rsnClssCd === "006") || (formUpclssCd === "09" && rsnClssCd === "009")) {
        $c.util.getComponent('slc_inqdisclsTpCd').setDisabled(false);
        $c.util.getComponent('slc_inqdisclsContnTpCd').setDisabled(false);
        scwin.changeInqdisclsInfo2();
    } else {
        $c.util.getComponent('slc_inqdisclsTpCd').setDisabled(true);
        $c.util.getComponent('slc_inqdisclsContnTpCd').setDisabled(true);
        $c.util.getComponent('slc_inqdisclsAnsTpCd').setDisabled(true);
    }
};

/**
 * @method
 * @name changeInqdisclsInfo2
 * @description change Inqdiscls Info2 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeInqdisclsInfo2 = function () {
    if ($c.util.getComponent('slc_inqdisclsTpCd').getValue() === "A") {
        $c.util.getComponent('slc_inqdisclsAnsTpCd').setDisabled(false);
    } else {
        $c.util.getComponent('slc_inqdisclsAnsTpCd').setDisabled(true);
    }
};

/**
 * @method
 * @name findRsnClasses
 * @description find Rsn Classes 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findRsnClasses = async function () {
    scwin.form_editForm.action = "/filing/updateForm.do";
    $c.util.getComponent('dma_UpdateReq').set('method', "findReasonClasses");
    scwin.dataDiv = "reasonClass";
    await scwin.tx_findRsnClasses_xhr();
    scwin.selectedClass("rsnClssCd");
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    ($c.util.getComponent("document.all.select_" + scwin.dataDiv) && $c.util.getComponent("document.all.select_" + scwin.dataDiv).setValue) ? $c.util.getComponent("document.all.select_" + scwin.dataDiv).setValue(responseText) : (($c.util.getComponent("document.all.select_" + scwin.dataDiv) && $c.util.getComponent("document.all.select_" + scwin.dataDiv).setText) ? $c.util.getComponent("document.all.select_" + scwin.dataDiv).setText(responseText) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "document.all.select_" + scwin.dataDiv), void (responseText)));
};

/**
 * @method
 * @name selectedClass
 * @description selected Class 처리
 * @param {String} objNm objNm
 * @returns {void}
 * @hidden N
 */
scwin.selectedClass = function (objNm) {
    const _options = editForm[objNm].options;
    const optVal = $c.util.getComponent('slc_rsnClssCd').getValue();
    for (let i = 0; i < _options.length; i++) {
        if (_options[i].value === optVal) {
            _options[i].selected = true;
            break;
        }
    }
};
